BOOL ReadLicenseScopes(wStream* s, SCOPE_LIST* scopeList)
{
    UINT32 scopeCount;

    if (!s || !scopeList)
        return FALSE;

    if (Stream_GetRemainingLength(s) < 4)
        return FALSE;

    Stream_Read_UINT32(s, scopeCount);

    if (scopeCount > 0xFFFFFFFF / sizeof(LICENSE_BLOB))
        return FALSE;

    scopeList->count = scopeCount;
    scopeList->scopes = (LICENSE_BLOB*)malloc(scopeCount * sizeof(LICENSE_BLOB));

    if (!scopeList->scopes)
        return FALSE;

    for (UINT32 i = 0; i < scopeCount; i++)
    {
        LICENSE_BLOB* blob = &scopeList->scopes[i];

        if (Stream_GetRemainingLength(s) < sizeof(UINT32))
            return FALSE;

        Stream_Read_UINT32(s, blob->length);

        if (blob->length > 0xFFFFFFFF / sizeof(UINT8))
            return FALSE;

        if (Stream_GetRemainingLength(s) < blob->length)
            return FALSE;

        blob->data = (UINT8*)malloc(blob->length);

        if (!blob->data)
            return FALSE;

        Stream_Read(s, blob->data, blob->length);
    }

    return TRUE;
}
